"""Derive phone daylight presentation from the approved layout, without a second UI.

Run after editing navy-mobile.css, glass-mobile.css or phone-iptv.css.
Only phone presentation is emitted; TV and provider data are untouched.
Developer dependency: tinycss2 (also used by the presentation audit).
"""
from pathlib import Path
import colorsys
import re
import tinycss2 as css
from tinycss2.color3 import parse_color

ROOT = Path(__file__).resolve().parent
PAINT = {'color','background','background-color','background-image','border','border-color',
         'border-top','border-bottom','border-left','border-right','border-inline',
         'border-top-color','border-bottom-color','box-shadow','text-shadow','fill','stroke',
         '-webkit-text-fill-color','outline','outline-color','caret-color','accent-color'}

def tone(token, prop, selected=False):
    try: value = parse_color(token)
    except (TypeError, AttributeError): value = None
    if not value or value == 'currentColor': return None
    r,g,b,a = value
    if not a: return 'transparent'
    h,l,s = colorsys.rgb_to_hls(r,g,b)
    text = prop in {'color','fill','stroke','-webkit-text-fill-color','caret-color'} or any(x in prop for x in ['text','muted','faint','ink','accent'])
    edge = 'border' in prop or 'outline' in prop or prop.endswith('line')
    blue = .55 < h < .72 and s > .6 and b > .5
    purple = .72 < h < .88 and s > .25
    red = (h < .07 or h > .90) and s > .35
    if text:
        if selected: return '#ffffff'
        if blue and l < .68: return '#174fc9'
        if purple: return '#7040bd'
        if red: return '#a3264b'
        if .43 < h < .56 and s > .35: return '#08749a'
        return '#193352' if l > .83 or l < .4 else '#4e6381'
    if edge: return '#2463eb' if blue else '#dce5f1'
    if 'shadow' in prop: return 'rgba(25,51,82,.07)'
    if blue: return '#2463eb' if l < .7 and a > .65 else '#edf3ff'
    if purple: return '#f0eafa'
    if red: return '#fff0f3'
    # Opaque sheets and white cards remain readable over every underlying page.
    return '#ffffff'

def paint(tokens, prop, selected=False):
    output=[]
    for token in tokens:
        color=tone(token,prop,selected)
        if color is not None: output.append(color)
        elif token.type=='function' and token.lower_name not in {'url','var'}:
            output.append(token.name+'('+paint(token.arguments,prop,selected)+')')
        else: output.append(css.serialize([token]))
    return ''.join(output)

def selectors(prelude):
    groups=[[]]
    for token in prelude:
        if token.type=='literal' and token.value==',': groups.append([])
        else: groups[-1].append(token)
    out=[]
    for group in groups:
        value=css.serialize(group).strip()
        if not value: continue
        value=value.replace('html:not([data-app-appearance=dark])','html[data-app-appearance=light]').replace('html:not([data-app-appearance=light])','html[data-app-appearance=light]')
        value=value.replace('[data-app-appearance=dark]','[data-app-appearance=light]')
        if value.startswith('html') and '[data-app-appearance=light]' not in value: value='html[data-app-appearance=light]'+value[4:]
        elif value.startswith('html'): pass
        elif value.startswith(':root'): value='html[data-app-appearance=light]'+value[5:]
        else: value='html[data-app-appearance=light] '+value
        out.append(value)
    return ','.join(out)

def derive(source):
    result=[]
    for rule in css.parse_stylesheet(source,skip_comments=True,skip_whitespace=True):
        if rule.type=='at-rule':
            if rule.lower_at_keyword in {'media','supports'} and rule.content:
                result.append('@'+rule.at_keyword+' '+css.serialize(rule.prelude)+'{'+derive(css.serialize(rule.content))+'}')
            continue
        if rule.type!='qualified-rule': continue
        original=css.serialize(rule.prelude)
        if any(x in original for x in ['#preview','.preview-main','.preview-ridge','#theme-preview']): continue
        declarations=css.parse_declaration_list(rule.content,skip_comments=True,skip_whitespace=True)
        selected=any(d.type=='declaration' and d.lower_name in {'background','background-color'} and re.search(r'#(?:2463eb|1263ed|1674f7|1461e8|0b52db)\b', css.serialize(d.value).lower()) for d in declarations)
        keep_geometry='[data-app-appearance=dark]' in original
        parts=[]
        for d in declarations:
            if d.type!='declaration': continue
            if d.lower_name not in PAINT and not d.name.startswith('--') and not keep_geometry: continue
            if d.name.startswith('--') and ('mask' in d.name or 'url(' in css.serialize(d.value)): continue
            value=paint(d.value,d.lower_name,selected)
            parts.append(d.name+':'+value+'!important')
        if parts: result.append(selectors(rule.prelude)+'{'+ ';'.join(parts)+'}')
    return '\n'.join(result)

def build():
    host='\n'.join((ROOT/'assets/ui'/name).read_text(encoding='utf-8') for name in ['navy-mobile.css','glass-mobile.css'])
    phone=(ROOT/'phone-iptv.css').read_text(encoding='utf-8').split('/* Daylight appearance overlay */')[0]
    network='\n'.join((ROOT.parent/'tv-project/app/network'/name).read_text(encoding='utf-8') for name in ['network.css','premium-network.css'])
    (ROOT/'phone-network.css').write_text(NETWORK_BASE+derive(network),encoding='utf-8')
    (ROOT/'assets/ui/daylight-mobile.css').write_text('/* Phone daylight palette; generated by mobile-app/theme_daylight.py. */\n'+derive(host)+HOST_FIXES,encoding='utf-8')
    (ROOT/'phone-iptv.css').write_text(phone+'\n/* Daylight appearance overlay */\n'+derive(phone)+PHONE_FIXES+PHONE_STATUS_FIXES+PHONE_READABILITY_FIXES+PHONE_NAV_LIST_FIXES+PHONE_FOOTER_TOOLS_FIXES+PHONE_TOOL_SHEETS_FIXES,encoding='utf-8')

